'use strict';

const fs = require('node:fs');
const path = require('node:path');

const ENDPOINT = process.env.STATUS_ENDPOINT || 'http://127.0.0.1:61826/status';
const OUTPUT_DIR = path.join(__dirname, 'results');
const OUTPUT_FILE = path.join(OUTPUT_DIR, 'status.json');
const TIMEOUT_MS = 10000;

async function fetchStatus(endpoint) {
  const response = await fetch(endpoint, { signal: AbortSignal.timeout(TIMEOUT_MS) });
  const body = (await response.text()).trim();

  if (!response.ok) {
    throw new Error(`GET ${endpoint} failed with HTTP ${response.status}`);
  }

  return body;
}

async function main() {
  const body = await fetchStatus(ENDPOINT);
  const { status } = JSON.parse(body);

  if (status !== 200) {
    throw new Error(`Expected status=200 in response, got ${status}`);
  }

  fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  fs.writeFileSync(OUTPUT_FILE, body);

  console.log(`Wrote ${path.relative(__dirname, OUTPUT_FILE)} (status=${status})`);
}

main().catch((error) => {
  console.error(`client failed: ${error.message}`);
  process.exitCode = 1;
});

